await page.getByText('Переименовать',{exact:true}).waitFor();
if(await trigger.getAttribute('aria-expanded')"'!=='"'true')throw Error('Missing expanded state');
await page.screenshot({path:'/tmp/kontur-menu.png',fullPage:true});
await page.keyboard.press('Escape');
await page.getByText('Переименовать',{exact:true}).waitFor({state:'hidden'});
await trigger.click();
await page.getByRole('heading',{name:'Недавние документы'}).click();
await page.getByText('Переименовать',{exact:true}).waitFor({state:'hidden'});
await trigger.focus();await page.keyboard.press('Enter');await page.keyboard.press('ArrowDown');await page.keyboard.press('Enter');
await page.getByRole('heading',{name:'Переименовать документ'}).waitFor();
await page.getByLabel('Название документа',{exact:true}).fill('Обновлённая стратегия');
await page.getByRole('button',{name:'Сохранить',exact:true}).click();
await page.getByRole('button',{name:'Действия: Обновлённая стратегия'}).click();
await page.getByText('Создать копию',{exact:true}).click();
await page.getByRole('button',{name:'Действия: Обновлённая стратегия — копия'}).waitFor();
await page.reload();await page.getByRole('button',{name:'Действия: Обновлённая стратегия — копия'}).waitFor();
await page.getByRole('button',{name:'Действия: Обновлённая стратегия — копия'}).click();
await page.getByText('Удалить',{exact:true}).click();
await page.getByRole('button',{name:'Удалить',exact:true}).click();
await page.getByRole('button',{name:'Действия: Обновлённая стратегия — копия'}).waitFor({state:'hidden'});
await page.setViewportSize({width:390,height:844});await page.screenshot({path:'/tmp/kontur-mobile.png',fullPage:true});
if(await page.evaluate(()=>document.documentElement.scrollWidth>window.innerWidth))throw Error('Mobile overflow');
await page.getByRole('button',{name:'Действия: Обновлённая стратегия'}).click();await page.getByText('Скачать документ',{exact:true}).waitFor();
